class GlobalDataClass {
public:
    bool isCheatUnlocked(int whichCheat) const;
};

extern GlobalDataClass globalCareerData;

class PanelQuad {
    char data[0x194];
public:
    virtual ~PanelQuad();
    virtual void Init(float, float, float, float,
                      float, float, float, float,
                      float, float, float, float,
                      float, void *);
    virtual void TurnOn(bool on);
};

class CheatCodeMenu {
    char data[0x168];
    int menu_entry_cheat_index[2];
    void *sys;
    int next_down;
    int next_up;
    void *toggle_state[2];
    PanelQuad *arrow_up;
    PanelQuad *arrow_down;
public:
    void ResetUpDownArrows();
};

void CheatCodeMenu::ResetUpDownArrows()
{
    int i;
    if(menu_entry_cheat_index[0] != 0)
    {
        for(i = menu_entry_cheat_index[0] - 1; i >= 0; i--)
            if(globalCareerData.isCheatUnlocked(i))
                break;
        next_up = i;
    }
    else
        next_up = -1;

    if(menu_entry_cheat_index[2 - 1] != 22 - 1 && menu_entry_cheat_index[2 - 1] != -1)
    {
        for(i = menu_entry_cheat_index[2 - 1] + 1; i < 22; i++)
            if(globalCareerData.isCheatUnlocked(i))
                break;
        if(i != 22)
            next_down = i;
        else
            next_down = -1;
    }
    else
        next_down = -1;

    if(next_up != -1)
        arrow_up->TurnOn(true);
    else
        arrow_up->TurnOn(false);

    if(next_down != -1)
        arrow_down->TurnOn(true);
    else
        arrow_down->TurnOn(false);
}
